import React, { useEffect, useState } from 'react';
import { Navigate } from 'react-router-dom';
import { Box, CircularProgress } from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import {
  clearPartnerPortalSession,
  persistPartnerPortalSession,
} from '../../utils/partnerPortalSession';

interface PartnerRouteProps {
  children: React.ReactNode;
}

const PartnerRoute: React.FC<PartnerRouteProps> = ({ children }) => {
  const [checking, setChecking] = useState(true);
  const [isPartner, setIsPartner] = useState(false);

  useEffect(() => {
    const validate = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        setIsPartner(false);
        setChecking(false);
        return;
      }

      try {
        const response = await axios.get(buildApiUrl('/partner-account/me'), {
          headers: { Authorization: `Bearer ${token}` },
        });
        const user = response.data?.data?.user;
        const partner = response.data?.data?.partner;
        if (user?.role === 'partner' && partner) {
          persistPartnerPortalSession(user, partner, token);
          setIsPartner(true);
        } else {
          clearPartnerPortalSession();
          setIsPartner(false);
        }
      } catch {
        clearPartnerPortalSession();
        localStorage.removeItem('token');
        setIsPartner(false);
      } finally {
        setChecking(false);
      }
    };

    validate();
  }, []);

  if (checking) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (!isPartner) {
    return <Navigate to="/login" replace />;
  }

  return <>{children}</>;
};

export default PartnerRoute;
