import React from 'react';
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Stack,
  Typography,
} from '@mui/material';
import AutoFixHighIcon from '@mui/icons-material/AutoFixHigh';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { Link as RouterLink } from 'react-router-dom';
import { useWarningResolution, type ApplicationWarning } from '../../hooks/useWarningResolution';
import {
  remediationActionLabelForBlockedReason,
  remediationLinkForBlockedReason,
} from '../../constants/reportingUxLabels';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';
type ApplicationWarningResolverProps = {
  warnings: ApplicationWarning[];
  period?: string;
  documentId?: string;
  onResolved?: () => void;
  compact?: boolean;
  showManualActions?: boolean;
  /** When false, hide Fix with AI (use when parent already shows Upload bills / primary CTA). */
  showAiResolve?: boolean;
};

const resolveManualLink = (warning: ApplicationWarning): string | null => {
  if (warning.hubLink) {
    return warning.hubLink;
  }
  const type = String(warning.type || '').toLowerCase();
  if (type.includes('ocr') || type.includes('document')) {
    return DOCUMENT_UPLOAD_PATH;
  }
  if (type.includes('spend_proxy') || type.includes('tier1') || type.includes('inventory_quality')) {
    return '/compliance/india?section=data-sync';
  }
  if (type.includes('assurance') || type.includes('iso')) {
    return '/compliance/india?section=iso-assurance';
  }
  if (type.includes('cbam') || type.includes('export')) {
    return '/compliance/export?section=cbam';
  }
  const message = warning.message || warning.action || warning.detail || '';
  return remediationLinkForBlockedReason(message);
};

const resolveManualLabel = (warning: ApplicationWarning, fallbackMessage: string): string => {
  if (warning.action) {
    return warning.action;
  }
  const message = warning.message || warning.detail || fallbackMessage;
  return remediationActionLabelForBlockedReason(message);
};

/** True when the gap is “go upload a bill/document” — AI cannot create those files. */
const isUploadOnlyGap = (warning: ApplicationWarning): boolean => {
  const text = [warning.message, warning.action, warning.detail]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  if (!text) return false;
  // Keep AI for OCR quality / reprocess — those are not “missing file” gaps.
  if (/\bocr\b|confidence|reprocess|quality/.test(text) && !/\bupload\b/.test(text)) {
    return false;
  }
  return (
    /\bupload (next )?bills?\b/.test(text)
    || /\bupload (a |your |missing )?documents?\b/.test(text)
    || /\bmissing (utility )?bills?\b/.test(text)
    || /\bno bills? (uploaded|on file)\b/.test(text)
    || /^upload\b/.test(text.trim())
    || /\badd (electricity|fuel|utility) (bills?|data)\b/.test(text)
  );
};

const ApplicationWarningResolver: React.FC<ApplicationWarningResolverProps> = ({
  warnings,
  period = 'annual',
  documentId,
  onResolved,
  compact = false,
  showManualActions = true,
  showAiResolve = true,
}) => {
  const { resolving, error, result, resolveWarnings } = useWarningResolution();

  if (!warnings.length) {
    return null;
  }

  const handleResolve = async () => {
    const payload = await resolveWarnings(warnings, { period, documentId });
    if (payload?.resolvedCount) {
      onResolved?.();
    }
  };

  const primaryWarning = warnings[0];
  const uploadOnly = isUploadOnlyGap(primaryWarning);
  // Upload/bill gaps need documents — AI cannot replace the upload step.
  const aiEnabled = showAiResolve && !uploadOnly;
  const manualLink = showManualActions ? resolveManualLink(primaryWarning) : null;
  const manualLabel = resolveManualLabel(primaryWarning, 'Fix manually');

  if (!aiEnabled && !manualLink) {
    return null;
  }

  if (compact) {
    return (
      <Box sx={{ mt: 1 }}>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          {manualLink ? (
            <Button
              size="small"
              variant="contained"
              component={RouterLink}
              to={manualLink}
              endIcon={<ArrowForwardIcon />}
            >
              {manualLabel}
            </Button>
          ) : null}
          {aiEnabled ? (
            <Button
              size="small"
              variant="outlined"
              disabled={resolving}
              onClick={() => void handleResolve()}
              startIcon={resolving ? <CircularProgress size={14} /> : <AutoFixHighIcon />}
            >
              {resolving ? 'Fixing with AI…' : 'Fix with AI'}
            </Button>
          ) : null}
        </Stack>
        {error ? (
          <Typography variant="caption" color="error" display="block" sx={{ mt: 0.5 }}>
            {error}
          </Typography>
        ) : null}
        {result?.message ? (
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
            {result.message}
          </Typography>
        ) : null}
      </Box>
    );
  }

  return (
    <Alert
      severity="warning"
      sx={{ mb: 2 }}
      action={(
        <Stack direction="row" spacing={1}>
          {manualLink ? (
            <Button
              color="inherit"
              size="small"
              component={RouterLink}
              to={manualLink}
            >
              {manualLabel}
            </Button>
          ) : null}
          {aiEnabled ? (
            <Button
              color="inherit"
              size="small"
              disabled={resolving}
              onClick={() => void handleResolve()}
              startIcon={resolving ? <CircularProgress size={16} color="inherit" /> : <AutoFixHighIcon />}
            >
              {resolving ? 'Resolving…' : 'Resolve with AI'}
            </Button>
          ) : null}
        </Stack>
      )}
    >
      <Typography variant="subtitle2" gutterBottom>
        {warnings.length === 1 ? 'Issue detected' : `${warnings.length} issues detected`}
      </Typography>
      <Stack spacing={0.25}>
        {warnings.slice(0, 3).map((warning) => (
          <Typography key={warning.message || warning.action || warning.type} variant="body2">
            • {warning.message || warning.action || warning.detail}
          </Typography>
        ))}
      </Stack>
      {uploadOnly ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
          Upload the missing bills or documents first — AI cannot create those files for you.
        </Typography>
      ) : null}
      {error ? (
        <Typography variant="caption" color="error" display="block" sx={{ mt: 1 }}>
          {error}
        </Typography>
      ) : null}
      {result?.message ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
          {result.message}
        </Typography>
      ) : null}
    </Alert>
  );
};

export default ApplicationWarningResolver;
